static EVP_MAC *mac;                 /* EVP_MAC_fetch(NULL, "HMAC", NULL) at startup */
static unsigned char prev[SHA256_DIGEST_LENGTH]; static size_t prev_len;
int audit_write(struct sink *s, const char *canon, size_t n) {
    unsigned char tag[SHA256_DIGEST_LENGTH]; size_t tag_len = sizeof tag;
    if (!EVP_MAC_init(ctx, key, key_len, params)          /* params: digest = SHA256 */
        || !EVP_MAC_update(ctx, prev, prev_len)           /* previous tag binds history */
        || !EVP_MAC_update(ctx, (const unsigned char *)canon, n)
        || !EVP_MAC_final(ctx, tag, &tag_len, sizeof tag)) return -1;
    if (sink_append_durable(s, tag, tag_len, canon, n) < 0) return -1;  /* O_APPEND, fsync */
    memcpy(prev, tag, tag_len); prev_len = tag_len;
    return 0;
}
